SELECT percentile_cont(0.75) within GROUP (ORDER BY (value - valueuom)) AS score_75th_percentile, (SELECT COUNT(*) * 100.0 / NULLIF(COUNT(DISTINCT subject_id), 0) FROM patient_data WHERE age >= score_75th_percentile) AS mortality_rate, AVG(los) AS average_length_of_stay, (SELECT COUNT(*) * 100.0 / NULLIF(COUNT(DISTINCT subject_id), 0) FROM patient_data) AS total_patients, (SELECT COUNT(*) * 100.0 / NULLIF(COUNT(DISTINCT subject_id), 0) FROM patient_data WHERE age < score_75th_percentile) AS critical_lab_rate FROM instability_score JOIN patient_data ON patient_data.subject_id = instability_score.labevent_id JOIN mortality_data ON mortality_data.subject_id = patient_data.subject_id;